import {readFinancialCsv,reviewFinancialCsv,applyFinancialCsv} from './finance-import.mjs';
import {toCsv} from './finance.mjs';
import {escapeHtml as esc,money} from './core.mjs';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export function createFinanceImportUI(ctx){
 let epoch=0,busy=false,pending=null;
 const message=text=>{const el=document.querySelector('#csv-error');if(el)el.textContent=text;};
 function cancelPending(){epoch++;pending=null;busy=false;}
 const show=body=>ctx.modal('Importar lançamentos CSV',body+'<p id="csv-error" role="alert" tabindex="-1"></p>');
 async function run(work){if(busy)return;busy=true;const version=epoch;message('');try{await work(()=>version===epoch);}catch(e){if(version===epoch)message(e.message);}finally{if(version===epoch)busy=false;}}
 function open(){cancelPending();const accounts=ctx.getState().accounts.filter(a=>!a.archived);show(`<p>Leia um CSV no aparelho, escolha as colunas e revise cada registro antes de guardar na sua conta Mentra. O arquivo não é enviado ao banco nem para a IA. Os lançamentos confirmados serão sincronizados com sua conta.</p><p>Somente entradas e saídas em reais. Transferências entre suas contas, cartões, faturas e baixas vinculadas precisam de seus fluxos próprios. A importação não realiza pagamentos.</p>${accounts.length?`<form id="csv-file-form" class="form-stack"><label>Conta que receberá os lançamentos<select name="accountId" required><option value="">Escolha uma conta ativa</option>${accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label><label>Separador do CSV<select name="delimiter"><option value=";">Ponto e vírgula (;)</option><option value=",">Vírgula (,)</option><option value="tab">Tabulação</option></select></label><label>Arquivo CSV em UTF-8, até 200 KB e cem registros<input type="file" name="file" accept=".csv,text/csv" required></label><button type="submit" class="primary">Ler e escolher colunas</button></form>`:'<p>Cadastre uma conta manual ativa em Meu dinheiro → Contas antes de importar.</p>'}<button type="button" class="text-link" data-action="csv-template">Baixar modelo CSV</button>`);}
 function column(label,key,parsed,candidates,optional=false){const found=parsed.headers.findIndex(h=>candidates.includes(normalize(h)));return `<label>${label}<select name="${key}" ${optional?'':'required'}><option value="" ${found<0?'selected':''}>${optional?(key==='type'?'Usar sinal do valor (+ entrada, − saída)':key==='category'?'Usar categoria Outros':'Sem identificador da origem'):'Escolha a coluna'}</option>${parsed.headers.map((h,i)=>`<option value="${i}" ${found===i?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`;}
 function mapping(parsed,accountId){const account=ctx.getState().accounts.find(a=>a.id===accountId);show(`<p>Destino: <strong>${esc(account?.name)}</strong>. ${parsed.rows.length} registros lidos. Confira as colunas e os formatos; nada foi guardado.</p><form id="csv-mapping-form" class="form-stack">${column('Data','date',parsed,['data','date'])}${column('Descrição','title',parsed,['descricao','description','historico'])}${column('Valor','amount',parsed,['valor','valor em reais','value','amount'])}${column('Tipo de movimento (opcional)','type',parsed,['tipo','type'],true)}${column('Categoria (opcional)','category',parsed,['categoria','category'],true)}${column('Identificador único da origem (opcional)','externalId',parsed,['id','identificador','identificador de origem'],true)}<p class="form-help">Use identificadores que sejam únicos na conta bancária de origem. Sem eles, detectamos o mesmo arquivo e sinalizamos semelhanças; arquivos diferentes ainda exigem conferência de duplicidades.</p><label>Formato de data<select name="dateFormat"><option value="iso">Ano-mês-dia (2026-10-29)</option><option value="br">Dia/mês/ano (29/10/2026)</option></select></label><label>Formato do valor em reais<select name="amountFormat"><option value="brl">Vírgula decimal (1.234,56)</option><option value="decimal">Ponto decimal, sem milhar (1234.56)</option></select></label><label>Situação de todos os registros selecionados<select name="status"><option value="actual">Realizado — afeta o saldo informado</option><option value="estimated">Previsão — não afeta o saldo realizado</option></select></label><label>Forma de pagamento de todos os registros<select name="paymentMethod"><option value="other">Outro / não informado</option><option value="pix">Pix</option><option value="debit">Débito</option><option value="cash">Dinheiro</option><option value="boleto">Boleto</option><option value="transfer">Transferência bancária</option></select></label><p>Se usar coluna de tipo, informe Entrada ou Saída com valores positivos. Sem coluna de tipo, valores negativos são saídas e positivos são entradas.</p><details><summary>Primeiros registros do arquivo</summary><div class="csv-sample">${parsed.rows.slice(0,3).map(row=>`<p>${row.map(esc).join(' · ')}</p>`).join('')}</div></details><div class="modal-actions"><button type="button" class="outline" data-action="csv-open">Voltar</button><button type="submit" class="primary">Revisar registros</button></div></form>`);}
 const labels={new:'Novo registro',possible:'Possível duplicidade — confira antes de selecionar',duplicate:'Já importado — não será repetido',conflict:'Origem já importada com dados diferentes — confira o lançamento existente',invalid:'Registro inválido — corrija no arquivo'};
 function reviewMarkup(review){return `<p>Destino: <strong>${esc(review.accountName)}</strong>. Selecione somente o que deseja adicionar. Registros com possível duplicidade começam desmarcados. Nenhum lançamento existente será alterado.</p><p>Situação: <strong>${review.status==='actual'?'Realizado':'Previsão'}</strong>. Forma de pagamento: ${esc(({other:'Outro / não informado',pix:'Pix',debit:'Débito',cash:'Dinheiro',boleto:'Boleto',transfer:'Transferência bancária'})[review.paymentMethod])}.</p><form id="csv-confirm-form"><ul class="sync-differences csv-review">${review.items.map(item=>{const r=item.draft,enabled=['new','possible'].includes(item.status);return `<li><label class="check-field"><input type="checkbox" name="rows" value="${item.index}" ${item.status==='new'?'checked':''} ${enabled?'':'disabled'}><span>Registro ${item.index+1} · ${esc(r.title||'Sem descrição')}<br>${esc(r.date)} · ${r.type==='income'?'Entrada':r.type==='expense'?'Saída':'Tipo inválido'} · ${Number.isInteger(r.cents)?money(r.cents):'Valor inválido'}</span></label><p>${esc(labels[item.status])}</p>${item.errors.length?`<p class="form-error">${item.errors.map(esc).join(' ')}</p>`:''}</li>`;}).join('')}</ul><p id="csv-totals" role="status"></p><label class="check-field"><input type="checkbox" name="confirmed" required><span>Conferi a conta, as datas, os valores e possíveis duplicidades dos registros selecionados.</span></label><div class="modal-actions"><button type="button" class="outline" data-action="csv-close">Cancelar</button><button type="submit" class="primary">Confirmar e guardar selecionados</button></div></form>`;}
 function updateTotals(form){if(!pending?.review)return;const selected=new Set(new FormData(form).getAll('rows').map(Number)),items=pending.review.items.filter(i=>selected.has(i.index)&&['new','possible'].includes(i.status)),sum=type=>items.filter(i=>i.draft.type===type).reduce((n,i)=>n+i.draft.cents,0),el=document.querySelector('#csv-totals');if(el)el.textContent=`${items.length} selecionados · entradas ${money(sum('income'))} · saídas ${money(sum('expense'))}.`;const submit=form.querySelector?.('button[type=submit]');if(submit)submit.disabled=items.length===0;}
 function handleClick(action){if(!action.startsWith('csv-'))return false;if(action==='csv-open')open();if(action==='csv-close')ctx.closeModal();if(action==='csv-template')ctx.download('mentra-modelo-importacao.csv',toCsv([{'Data':'2026-10-29','Descrição':'Exemplo de despesa','Valor':'-25,90','Categoria':'Outros','Identificador de origem':'exemplo-001'}]),'text/csv;charset=utf-8');return true;}
 function handleSubmit(form){if(!form.id.startsWith('csv-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}const values=Object.fromEntries(new FormData(form));
  if(form.id==='csv-file-form'){const file=form.querySelector('[name=file]')?.files?.[0];void run(async valid=>{const parsed=await readFinancialCsv(file,values.delimiter==='tab'?'\t':values.delimiter);if(!valid())return;pending={parsed,accountId:values.accountId};mapping(parsed,values.accountId);});}
  if(form.id==='csv-mapping-form'&&pending?.parsed){const chosen=pending;void run(async valid=>{const review=await reviewFinancialCsv(ctx.getState(),chosen.parsed,{...values,accountId:chosen.accountId});if(!valid())return;pending={...chosen,review};show(reviewMarkup(review));const form=document.querySelector('#csv-confirm-form');if(form)updateTotals(form);});}
  if(form.id==='csv-confirm-form'&&pending?.review){const chosen=pending.review,selected=new FormData(form).getAll('rows').map(Number);void run(async valid=>{if(!await ctx.flush())throw Error('Resolva a sincronização antes de importar.');if(!valid())return;const next=applyFinancialCsv(ctx.getState(),chosen,selected);ctx.setState(next);pending=null;ctx.save();ctx.closeModal();ctx.render();ctx.toast(`${selected.length} registros preparados para sincronização.`);});}
  return true;
 }
 function handleChange(event){if(event.target.name==='rows'&&event.target.closest('#csv-confirm-form')){updateTotals(event.target.closest('form'));return true;}return false;}
 return {open,handleClick,handleSubmit,handleChange,cancelPending};
}
